{
  "identity": {
    "name": "Crossflow Plumbing LLC",
    "location": "384 N Stierman Way, Eagle, Idaho 83616",
    "claims": [
      {
        "statement": "Crossflow Plumbing LLC is a locally owned plumbing company based in Eagle, Idaho.",
        "label": "fact",
        "sourceUrl": "https://crossflowplumbingllc.com/",
        "quote": "Crossflow Plumbing LLC is a locally owned plumbing company based in Eagle, Idaho."
      },
      {
        "statement": "The business lists its street address as 384 N Stierman Way, Eagle, Idaho 83616.",
        "label": "fact",
        "sourceUrl": "https://crossflowplumbingllc.com/contact/",
        "quote": "384 N Stierman Way Eagle, Idaho 83616"
      },
      {
        "statement": "[redacted] is the Owner and Founder of Crossflow Plumbing LLC.",
        "label": "fact",
        "sourceUrl": "https://crossflowplumbingllc.com/about-crossflow-plumbing/",
        "quote": "~ [redacted], Owner & Founder of Crossflow Plumbing"
      }
    ]
  },
  "industry": {
    "industry": "Residential Plumbing & Home Services",
    "activities": [
      "24/7 Emergency Plumbing",
      "Drain Cleaning & Hydro Jetting",
      "Water Heater Repair & Installation (Tank, Tankless, Hybrid, Gas, Electric)",
      "Leak Detection & Pipe Repair",
      "Sewer Line Inspection & Repair",
      "Plumbing Fixture, Water Softener & Filtration Installation"
    ],
    "claims": [
      {
        "statement": "The company provides emergency plumbing, drain cleaning, water heater repair, leak detection, and sewer line repair.",
        "label": "fact",
        "sourceUrl": "https://crossflowplumbingllc.com/contact/",
        "quote": "Crossflow Plumbing provides fast, professional plumbing services including emergency plumbing, drain cleaning, water heater repair, leak detection, and sewer line repair."
      },
      {
        "statement": "The company installs water filtration systems and water softeners in addition to plumbing fixtures.",
        "label": "fact",
        "sourceUrl": "https://crossflowplumbingllc.com/eagle-plumbing-company/",
        "quote": "Protect your plumbing and appliances from Idaho's hard water with professional softener installation."
      },
      {
        "statement": "The company operates across Eagle, Meridian, Boise, Nampa, Star, Kuna, Melba, and Middleton in Idaho's Treasure Valley.",
        "label": "fact",
        "sourceUrl": "https://crossflowplumbingllc.com/",
        "quote": "We proudly serve the entire Treasure Valley including Eagle, Meridian, Boise, Nampa, Star, Kuna, Melba, and Middleton."
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://crossflowplumbingllc.com/",
    "claims": [
      {
        "statement": "The official website advertises 24/7/365 emergency plumbing service and bilingual (English and Spanish) customer communication.",
        "label": "fact",
        "sourceUrl": "https://crossflowplumbingllc.com/about-crossflow-plumbing/",
        "quote": "We promise to answer the phone, we explain what’s going on in plain English (but we can also speak in Spanish if you need it)"
      },
      {
        "statement": "The homepage displays a counter stating 400+ happy customers and 24/7 emergency service.",
        "label": "fact",
        "sourceUrl": "https://crossflowplumbingllc.com/",
        "quote": "400+ Happy Customers 24/7 Emergency Service"
      },
      {
        "statement": "The water heater service page publishes starting installed prices for tank ($800) and tankless ($1,500+) water heaters.",
        "label": "fact",
        "sourceUrl": "https://crossflowplumbingllc.com/water-heater-repair-boise/",
        "quote": "That said, a new tank water heater is usually starting at $800 installed and tankless is $1,500 and up."
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The website states that all of its plumbers are fully licensed, insured, and experienced.",
        "label": "fact",
        "sourceUrl": "https://crossflowplumbingllc.com/",
        "quote": "Yes, all our plumbers are fully licensed, insured, and experienced."
      }
    ],
    "limitations": "Although the website states the business and its plumbers are licensed and insured, no specific Idaho plumbing contractor license number or state registration number is displayed on the pages read."
  },
  "existingSoftware": [
    {
      "product": "client.housecallpro.com widget",
      "purpose": "Customer reviews widget embedded via iframe on the homepage",
      "evidence": {
        "statement": "The homepage embeds an iframe from client.housecallpro.com for displaying reviews.",
        "label": "fact",
        "sourceUrl": "https://crossflowplumbingllc.com/",
        "quote": "https://client.housecallpro.com/reviews/widget/64a6cf54-1946-40dc-96c9-ccbb074bd969"
      }
    },
    {
      "product": "Housecall Pro field-service management platform",
      "purpose": "Field-service scheduling, dispatching, invoicing, and review management",
      "evidence": {
        "statement": "Because the homepage loads a widget from client.housecallpro.com, the company likely uses Housecall Pro as its field-service software.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    },
    {
      "product": "elementor / elementor-pro / hello-elementor / link-whisper-premium / google-site-kit",
      "purpose": "Website content management, page building, internal linking, and site event tracking",
      "evidence": {
        "statement": "The website loads scripts from wp-content/plugins/elementor, elementor-pro, link-whisper-premium, and google-site-kit.",
        "label": "fact",
        "sourceUrl": "https://crossflowplumbingllc.com/",
        "quote": "https://crossflowplumbingllc.com/wp-content/plugins/elementor-pro/assets/js/frontend.min.js?ver=4.3.1"
      }
    },
    {
      "product": "googletagmanager.com (GT-K52TXMCT)",
      "purpose": "Website analytics and tag management",
      "evidence": {
        "statement": "The website loads a Google Tag script with ID GT-K52TXMCT from www.googletagmanager.com.",
        "label": "fact",
        "sourceUrl": "https://crossflowplumbingllc.com/",
        "quote": "https://www.googletagmanager.com/gtag/js?id=GT-K52TXMCT"
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "The website captures service requests via standard HTTP POST forms asking for Full Name, Email Address, Phone Number, Service Needed, and Message.",
      "label": "fact",
      "sourceUrl": "https://crossflowplumbingllc.com/contact/",
      "quote": "Full Name Email Address Phone Number Service Needed Select a service"
    },
    {
      "statement": "The website does not embed an online booking widget or live chat widget on the pages read, relying instead on phone calls and POST forms.",
      "label": "inference",
      "sourceUrl": "https://crossflowplumbingllc.com/contact/",
      "quote": null
    },
    {
      "statement": "The company states it prioritizes emergency calls and aims to respond within 1 to 2 hours across the Treasure Valley.",
      "label": "fact",
      "sourceUrl": "https://crossflowplumbingllc.com/",
      "quote": "We prioritize emergency calls and typically respond within 1-2 hours depending on your location in the Treasure Valley."
    },
    {
      "statement": "The company regularly receives common customer inquiries regarding water heater pricing, running toilets, and emergency steps.",
      "label": "fact",
      "sourceUrl": "https://crossflowplumbingllc.com/water-heater-repair-boise/",
      "quote": "How much does a new water heater cost? We get that question often!"
    }
  ],
  "problems": [
    {
      "problem": "Web form leads submitted on the WordPress/Elementor site may require manual entry into the field-service software and may not receive an instant two-minute automated follow-up, risking lost leads during busy jobs or after hours.",
      "label": "hypothesis",
      "basis": "The site uses native POST forms on https://crossflowplumbingllc.com/ and https://crossflowplumbingllc.com/contact/ rather than an embedded field-service booking widget, though backend webhook automation cannot be ruled out from public pages."
    },
    {
      "problem": "Owner and technicians may face interruptions from routine questions or after-hours calls that could be triaged or answered automatically before dispatch.",
      "label": "hypothesis",
      "basis": "The company advertises 24/7/365 emergency response across eight Treasure Valley towns and notes frequent customer questions, with no automated chat or triage assistant observable on the site."
    },
    {
      "problem": "Tracking booked revenue, close rate, average ticket, and cost per booked job across lead sources may require manual consolidation across field-service, accounting, and marketing tools.",
      "label": "hypothesis",
      "basis": "The site uses googletagmanager.com and a client.housecallpro.com widget, suggesting multiple systems that owners often reconcile manually."
    }
  ],
  "existingSolutions": [
    {
      "solution": "Built-in online booking, lead capture, and automated text/email follow-ups within the company's existing field-service software (such as Housecall Pro)",
      "addresses": "Direct lead entry into field-service software and automated initial customer responses without custom middleware",
      "alreadyOwned": true
    },
    {
      "solution": "Native reporting dashboards within existing field-service software",
      "addresses": "Basic tracking of job revenue, average ticket, and technician performance",
      "alreadyOwned": true
    }
  ],
  "forgexSolutions": [
    {
      "name": "Revenue Leak Check",
      "kind": "catalog",
      "description": "One-week audit ($500 fixed price, credited in full toward any fix ordered within 30 days) to measure how many calls, web-form leads, and quotes slip through and quantify their value.",
      "problem": "Potential delay or drop-off between WordPress web-form inquiries, missed calls while on job sites, and booked jobs.",
      "whyNotExistingSoftware": "Field-service software only tracks leads that make it into the system; it does not audit unlogged phone calls, abandoned web forms, or cross-channel response delays."
    },
    {
      "name": "Lead-to-job pipeline",
      "kind": "catalog",
      "description": "Automated pipeline ($1,800 setup plus $149/month) ensuring every lead from the WordPress forms and other lead sources lands in the field-service software within two minutes, triggers an instant reply (in English or Spanish), and enforces callback reminders.",
      "problem": "Manual re-keying of Elementor POST form submissions and delayed response to urgent plumbing leads.",
      "whyNotExistingSoftware": "If the company prefers keeping its custom Elementor forms and multi-source lead capture rather than replacing them with a stock iframe widget, custom integration is needed to push leads into the field-service system and trigger immediate multi-step follow-up."
    },
    {
      "name": "Owner's Monday numbers",
      "kind": "catalog",
      "description": "Weekly one-page summary ($1,200 setup plus $99/month) combining field-service software, accounting, and ad account data into booked revenue, close rate, average ticket, cost per booked job by lead source, and money owed.",
      "problem": "Lack of unified visibility into true cost per booked job across marketing channels and accounting.",
      "whyNotExistingSoftware": "Standard field-service dashboards do not automatically reconcile ad spend and accounting receivables into a single weekly owner scorecard."
    }
  ],
  "feasibility": {
    "rating": "high",
    "explanation": "Connecting WordPress Elementor forms, phone/call logs, and major field-service management platforms via webhooks and APIs is straightforward and well-supported."
  },
  "aiDelivery": {
    "rating": "partly",
    "explanation": "Deterministic workflow automation should handle lead routing, CRM/field-service record creation, and KPI calculations, while AI agents can assist with classifying free-text form messages (e.g., distinguishing 24/7 emergencies from routine estimates) and drafting bilingual replies."
  },
  "humanReview": [
    "Owner or dispatcher confirmation before dispatching a plumber or committing to a specific arrival window for 24/7 emergency requests.",
    "Human review of any pricing estimates or non-standard troubleshooting advice before sending to a homeowner.",
    "Owner verification of lead-source attribution mappings during setup of the Owner's Monday numbers report."
  ],
  "risks": [
    {
      "type": "operational",
      "description": "In 24/7 emergency plumbing (such as burst pipes or sewer backups), an automated reply must never imply a technician is already en route unless confirmed by a human, as delays can result in severe property water damage."
    },
    {
      "type": "compliance",
      "description": "Automated SMS or voice follow-ups triggered from web forms or missed calls must comply with TCPA opt-in and disclosure requirements."
    },
    {
      "type": "security",
      "description": "Homeowner personally identifiable information (names, physical addresses, phone numbers, emails) must be transmitted securely over encrypted connections with least-privilege API keys."
    }
  ],
  "commercial": {
    "supportable": true,
    "value": "Illustrative gross revenue of $800 to $1,500+ per additional water heater installation recovered, or $9,600 to $18,000+ annually if 1 additional installation per month is captured.",
    "implementationCost": "$500 fixed price for the initial Revenue Leak Check (credited in full toward any fix ordered within 30 days); $1,800 setup plus $149/month for the Lead-to-job pipeline; or $1,200 setup plus $99/month for Owner's Monday numbers.",
    "assumptions": [
      "The website states on https://crossflowplumbingllc.com/water-heater-repair-boise/ that 'a new tank water heater is usually starting at $800 installed and tankless is $1,500 and up.'",
      "Illustrative assumption: faster automated lead capture and instant reply recovers 1 previously missed water heater installation lead per month (12 per year).",
      "Illustrative calculation: 1 job/month x $800 starting tank price = $800/month ($9,600/year), or 1 job/month x $1,500 starting tankless price = $1,500/month ($18,000/year) in gross revenue before labor and equipment costs."
    ]
  },
  "contacts": {
    "decisionMakerRoles": [
      "Owner & Founder"
    ],
    "people": [
      {
        "name": "[redacted]",
        "role": "Owner & Founder",
        "sourceUrl": "https://crossflowplumbingllc.com/about-crossflow-plumbing/",
        "quote": "~ [redacted], Owner & Founder of Crossflow Plumbing"
      }
    ],
    "channels": [
      {
        "kind": "email",
        "value": "[redacted]",
        "sourceUrl": "https://crossflowplumbingllc.com/contact/"
      }
    ]
  },
  "discovery": {
    "questions": [
      "How many plumbers and office staff are currently on your team, and how are incoming calls and web-form requests handled when everyone is on a job or after hours?",
      "Are you currently using Housecall Pro across the business, and do leads from your website's contact forms flow into it automatically or get entered by hand?",
      "Are you currently paying for leads (such as Google Ads or local lead services), and how do you track cost per booked job across those channels?",
      "Have you already turned on any built-in online booking or automated text follow-up inside your current field-service software?"
    ],
    "outreachSubject": "Question about Crossflow Plumbing's web form leads & after-hours calls",
    "outreachBody": "Hi [redacted],\n\nI was looking through crossflowplumbingllc.com and saw how you've built Crossflow Plumbing around fast 1-2 hour emergency response and upfront pricing across Eagle and the Treasure Valley.\n\nI noticed your site uses standard contact forms alongside your Housecall Pro reviews widget. When you and the team are under a house or handling after-hours calls, do web form inquiries and missed calls go straight into your dispatch software with an instant reply, or does someone have to enter and follow up on them manually?\n\nAt ForgeX, we offer a fixed-price Revenue Leak Check ($500, credited in full toward any fix you order within 30 days). In one week, we check how many calls, leads, and quotes slip through—and we also check whether tools you already pay for can solve it before recommending our Lead-to-job pipeline ($1,800 setup + $149/month). We don't promise specific results, just a clear look at where leads go.\n\nIf you're open to a brief conversation to see if this is relevant to your current setup, just reply to this email.\n\nBest regards,\n\n[Founder Name]\n[Founder Title], ForgeX\n[ForgeX Physical Postal Address]\n\nIf you prefer not to receive future emails from us, simply reply with \"unsubscribe\" or use [Opt-Out Link/Instructions] and we will remove you immediately."
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://crossflowplumbingllc.com/",
        "usedFor": "Business identity, service areas, 24/7 emergency response claims, Housecall Pro review widget iframe, Elementor/WordPress scripts, Google Tag ID, and owner name."
      },
      {
        "url": "https://crossflowplumbingllc.com/about-crossflow-plumbing/",
        "usedFor": "Owner and Founder verification ([redacted]), physical street address, business email, and bilingual (English/Spanish) service statement."
      },
      {
        "url": "https://crossflowplumbingllc.com/contact/",
        "usedFor": "Permitted business contact channel ([redacted]), physical address, and web-form structure."
      },
      {
        "url": "https://crossflowplumbingllc.com/emergency-plumbing-eagle-boise-near-me/",
        "usedFor": "Emergency plumbing service scope and diagnostic equipment claims."
      },
      {
        "url": "https://crossflowplumbingllc.com/eagle-plumbing-company/",
        "usedFor": "Local Eagle service offerings including water softeners, filtration systems, and sewer camera inspections."
      },
      {
        "url": "https://crossflowplumbingllc.com/blog/",
        "usedFor": "Content marketing activity and common customer inquiry topics."
      },
      {
        "url": "https://crossflowplumbingllc.com/water-heater-repair-boise/",
        "usedFor": "Published starting prices for installed tank ($800) and tankless ($1,500+) water heaters."
      }
    ],
    "limitations": [
      "Employee headcount is not stated on the website; while the site refers to 'our plumbers' and 'our team', it cannot be confirmed from public pages whether the company employs 10 to 75 staff or is a smaller crew.",
      "Whether the company pays for leads (e.g., paid search or lead-generation networks) cannot be confirmed from the website alone, although Google Tag (GT-K52TXMCT) is installed.",
      "No specific Idaho state plumbing contractor license number is listed on the website.",
      "Backend form routing (whether the WordPress POST forms trigger a webhook into Housecall Pro or simply send an email) is not observable from public page source."
    ]
  },
  "qualification": {
    "category": "pursue later",
    "rationale": "Crossflow Plumbing LLC is an owner-led residential plumbing contractor in Eagle, Idaho with a clear decision-maker (Owner [redacted]), a verified business contact channel ([redacted]), and observable evidence of using WordPress/Elementor POST forms alongside a client.housecallpro.com widget. However, because employee headcount (target 10-75 staff), paid lead spend, and whether web-form leads are handled manually or already automated in the backend are unconfirmed hypotheses rather than verified facts, 'pursue later' is the appropriate qualification."
  }
}
